/* Pictorial display layer: preserve the question-specific PNG generated by the bank. */
(function(){
  const card=()=>document.getElementById('questionCard');
  function style(){
    const c=card(); if(!c) return;
    c.querySelectorAll('.question-image-wrap img').forEach(img=>{
      img.loading='eager';
      img.decoding='async';
      img.style.display='block';
      img.style.width='100%';
      img.style.height='auto';
      img.style.maxWidth='1100px';
      img.style.margin='10px auto';
      img.style.objectFit='contain';
      img.style.borderRadius='14px';
    });
    c.querySelectorAll('.question-image-wrap').forEach(w=>{
      w.style.width='100%';
      w.style.maxWidth='1100px';
      w.style.margin='12px auto';
      w.style.overflow='hidden';
    });
  }
  const c=card();
  if(c){
    new MutationObserver(()=>style()).observe(c,{childList:true,subtree:true});
    style();
  }
})();
